#!/usr/bin/env python3
"""
Round 187o (culprits-tiles-more), 5 October 2026.

bii_nhm.py joins the museum's zip from pieces uploaded to bii/download/
(bii_part_aa, bii_part_ab, ...), because the whole file is 45.9 MB, over
GitHub's 25 MB upload limit. Written only if it differs.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, sys

FILES = {'scripts/bii_nhm.py': ''}


def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("round187o_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"round187o_tiles: wrote {path}")
    if not changed:
        print("round187o_tiles: already applied")


if __name__ == "__main__":
    main()
